function wornBadge(d){
  if(d===null)return{label:"Never recorded",tx:"#999",bg:"#F5F0EB"};
  if(d<90)    return{label:"Worn recently", tx:"#2E7D32",bg:"#E8F5E9"};
  if(d<365)   return{label:"This year",     tx:"#E65100",bg:"#FFF3E0"};
  if(d<730)   return{label:"1-2 yrs ago",   tx:"#BF360C",bg:"#FBE9E7"};
  return       {label:"Long overdue!",      tx:"#B71C1C",bg:"#FFEBEE"};
}
function genId(name,n){
  const parts=(name||"").trim().split(/\s+/).filter(Boolean);
  let prefix="MS";
  if(parts.length>=2){
    prefix=parts[0][0].toUpperCase()+parts[parts.length-1][0].toUpperCase();
  } else if(parts.length===1&&parts[0].length>=2){
    prefix=parts[0].slice(0,2).toUpperCase();
  }
  return prefix+String(n+1).padStart(2,"0");
}


/* ── PWA Install Banner ── */
function InstallBanner(){
  const[show,setShow]=useState(false);
  const[isIOS,setIOS]=useState(false);
  const[prompt,setPrompt]=useState(null);
  useEffect(()=>{
    const installed=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;
    if(installed)return;
    if(sessionStorage.getItem('mss-banner-off'))return;
    const ua=navigator.userAgent;
    if(/iphone|ipad|ipod/i.test(ua)){setIOS(true);setShow(true);}
    const handler=(e)=>{e.preventDefault();setPrompt(e);setShow(true);};
    window.addEventListener('beforeinstallprompt',handler);
    return()=>window.removeEventListener('beforeinstallprompt',handler);
  },[]);
  function dismiss(){sessionStorage.setItem('mss-banner-off','1');setShow(false);}
  async function install(){if(prompt){prompt.prompt();const{outcome}=await prompt.userChoice;if(outcome==='accepted')setShow(false);}}
  if(!show)return null;
  return(
    <div style={{position:'fixed',bottom:0,left:0,right:0,background:'linear-gradient(135deg,#6B1030,#8B1A3A)',padding:'14px 16px',zIndex:9998,boxShadow:'0 -4px 20px rgba(107,16,48,.3)',display:'flex',alignItems:'center',gap:12}}>
      <div style={{flex:1}}>
        <div style={{color:'#FFE8D0',fontWeight:700,fontSize:13,fontFamily:"'Lato',sans-serif",marginBottom:3}}>📱 Add to your Home Screen</div>
        {isIOS&&<div style={{color:'rgba(255,232,208,.8)',fontSize:11,fontFamily:"'Lato',sans-serif",lineHeight:1.5}}>Tap <strong style={{color:'#D4AF37'}}>Share ⬆️</strong> in Safari → <strong style={{color:'#D4AF37'}}>"Add to Home Screen"</strong></div>}
        {!isIOS&&!prompt&&<div style={{color:'rgba(255,232,208,.8)',fontSize:11,fontFamily:"'Lato',sans-serif",lineHeight:1.5}}>Tap <strong style={{color:'#D4AF37'}}>menu ⋮</strong> in Chrome → <strong style={{color:'#D4AF37'}}>"Add to Home Screen"</strong></div>}
        {prompt&&<div style={{color:'rgba(255,232,208,.8)',fontSize:11,fontFamily:"'Lato',sans-serif"}}>Install My Saree Story as an app on your device</div>}
      </div>
      {prompt&&<button onClick={install} style={{padding:'8px 16px',borderRadius:99,border:'none',background:'linear-gradient(135deg,#D4AF37,#B8902A)',color:'#fff',fontFamily:"'Lato',sans-serif",fontWeight:700,fontSize:12,cursor:'pointer',whiteSpace:'nowrap'}}>Install</button>}
      <button onClick={dismiss} style={{background:'none',border:'none',color:'rgba(255,232,208,.6)',fontSize:20,cursor:'pointer',padding:'0 4px'}}>✕</button>
    </div>
  );
}


